// 🧭 dynamic dense aliases é
export function zeta(i: u32, n: u32, value: f64): f64 {
  const original: f64[] = [-0, 0.1];
  const same = original;
  const châin: f64[] = same;
  châin[i] = value;
  same.length = n;
  return original[i];
}

export function alpha(i: u32, value: f64): f64 {
  const original: f64[] = [2.0];
  original[i] = value;
  return original[i];
}

